=== java/com/example/dealership/handover/HandoverReadinessCheck.java
     1	package com.example.dealership.handover;
     2	
     3	import java.time.LocalDate;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.Optional;
     7	
     8	import com.example.dealership.vehicledocument.VehicleDocument;
     9	import com.example.dealership.vehicledocument.VehicleDocumentStatus;
    10	import com.example.dealership.vehicledocument.VehicleDocumentType;
    11	
    12	/**
    13	 * Handover readiness rules (INTENT.md R10-R17), as plain code without Spring.
    14	 *
    15	 * <ul>
    16	 *     <li>Required: sales agreement, invoice, COC, OC policy; the registration power of attorney only when the
    17	 *     dealer registers the vehicle.</li>
    18	 *     <li>A required type without an active (non-rejected) document is missing.</li>
    19	 *     <li>An active pending document is NOT_VERIFIED.</li>
    20	 *     <li>An active document expiring before the handover date is EXPIRED; expiring on that day is fine. Without a
    21	 *     handover date, expiry is compared with today (Z4).</li>
    22	 *     <li>No handover date adds NO_HANDOVER_DATE with documentType null, so the vehicle is never ready.</li>
    23	 *     <li>Order (Z7): types in enum order, NOT_VERIFIED before EXPIRED, NO_HANDOVER_DATE last.</li>
    24	 * </ul>
    25	 */
    26	public final class HandoverReadinessCheck {
    27	
    28	    private static final List<VehicleDocumentType> ALWAYS_REQUIRED = List.of(
    29	            VehicleDocumentType.SALES_AGREEMENT,
    30	            VehicleDocumentType.INVOICE,
    31	            VehicleDocumentType.COC,
    32	            VehicleDocumentType.OC_POLICY);
    33	
    34	    private HandoverReadinessCheck() {
    35	    }
    36	
    37	    public static HandoverReadiness evaluate(boolean registeredByDealer, LocalDate plannedHandoverDate,
    38	            List<VehicleDocument> documents, LocalDate today) {
    39	        LocalDate validOn = plannedHandoverDate != null ? plannedHandoverDate : today;
    40	        List<VehicleDocumentType> missing = new ArrayList<>();
    41	        List<HandoverProblem> problems = new ArrayList<>();
    42	
    43	        for (VehicleDocumentType type : requiredTypes(registeredByDealer)) {
    44	            Optional<VehicleDocument> active = activeDocument(documents, type);
    45	            if (active.isEmpty()) {
    46	                missing.add(type);
    47	                continue;
    48	            }
    49	            VehicleDocument document = active.get();
    50	            if (document.getStatus() == VehicleDocumentStatus.PENDING) {
    51	                problems.add(new HandoverProblem(type, HandoverProblemReason.NOT_VERIFIED));
    52	            }
    53	            if (document.getExpiryDate() != null && document.getExpiryDate().isBefore(validOn)) {
    54	                problems.add(new HandoverProblem(type, HandoverProblemReason.EXPIRED));
    55	            }
    56	        }
    57	        if (plannedHandoverDate == null) {
    58	            problems.add(new HandoverProblem(null, HandoverProblemReason.NO_HANDOVER_DATE));
    59	        }
    60	
    61	        return new HandoverReadiness(missing.isEmpty() && problems.isEmpty(), List.copyOf(missing),
    62	                List.copyOf(problems));
    63	    }
    64	
    65	    private static List<VehicleDocumentType> requiredTypes(boolean registeredByDealer) {
    66	        List<VehicleDocumentType> required = new ArrayList<>();
    67	        for (VehicleDocumentType type : VehicleDocumentType.values()) {
    68	            if (ALWAYS_REQUIRED.contains(type)
    69	                    || (registeredByDealer && type == VehicleDocumentType.REGISTRATION_POA)) {
    70	                required.add(type);
    71	            }
    72	        }
    73	        return required;
    74	    }
    75	
    76	    private static Optional<VehicleDocument> activeDocument(List<VehicleDocument> documents, VehicleDocumentType type) {
    77	        return documents.stream()
    78	                .filter(document -> document.getType() == type)
    79	                .filter(document -> document.getStatus() != VehicleDocumentStatus.REJECTED)
    80	                .findFirst();
    81	    }
    82	}
