     9	import jakarta.validation.Constraint;
    10	import jakarta.validation.Payload;
    11	
    12	/** Cross-field rule reported on {@code expiryDate}, so the 400 has the usual {@code errors[{field}]} shape. */
    13	@Documented
    14	@Constraint(validatedBy = ExpiryDateNotBeforeIssueDateValidator.class)
    15	@Target(ElementType.TYPE)
    16	@Retention(RetentionPolicy.RUNTIME)
    17	public @interface ExpiryDateNotBeforeIssueDate {
    18	
    19	    String message() default "must not be before issue date";
    20	
    21	    Class<?>[] groups() default {};
    22	
    23	    Class<? extends Payload>[] payload() default {};
    24	}
=== java/com/example/dealership/vehicledocument/ExpiryDateNotBeforeIssueDateValidator.java
     1	package com.example.dealership.vehicledocument;
     2	
     3	import jakarta.validation.ConstraintValidator;
     4	import jakarta.validation.ConstraintValidatorContext;
     5	
     6	public class ExpiryDateNotBeforeIssueDateValidator
     7	        implements ConstraintValidator<ExpiryDateNotBeforeIssueDate, VehicleDocumentRequest> {
     8	
     9	    @Override
    10	    public boolean isValid(VehicleDocumentRequest request, ConstraintValidatorContext context) {
    11	        if (request == null || request.issueDate() == null || request.expiryDate() == null) {
    12	            return true;
    13	        }
    14	        if (!request.expiryDate().isBefore(request.issueDate())) {
    15	            return true;
    16	        }
    17	        context.disableDefaultConstraintViolation();
    18	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
    19	                .addPropertyNode("expiryDate")
    20	                .addConstraintViolation();
    21	        return false;
    22	    }
    23	}
