     1	package com.example.dealership.vehicledocument;
     2	
     3	import java.util.List;
     4	
     5	import com.example.dealership.error.ConflictException;
     6	import com.example.dealership.error.NotFoundException;
     7	import com.example.dealership.vehicle.VehicleRepository;
     8	
     9	import org.springframework.data.domain.Sort;
    10	import org.springframework.stereotype.Service;
    11	import org.springframework.transaction.annotation.Transactional;
    12	
    13	@Service
    14	@Transactional(readOnly = true)
    15	public class VehicleDocumentService {
    16	
    17	    private final VehicleDocumentRepository documentRepository;
    18	    private final VehicleRepository vehicleRepository;
    19	
    20	    public VehicleDocumentService(VehicleDocumentRepository documentRepository, VehicleRepository vehicleRepository) {
    21	        this.documentRepository = documentRepository;
    22	        this.vehicleRepository = vehicleRepository;
    23	    }
    24	
    25	    public List<VehicleDocumentResponse> findAll(Long vehicleId) {
    26	        requireVehicle(vehicleId);
    27	        return documentRepository.findAllByVehicleId(vehicleId, Sort.by("id")).stream()
    28	                .map(VehicleDocumentMapper::toResponse)
    29	                .toList();
    30	    }
    31	
    32	    public VehicleDocumentResponse findById(Long vehicleId, Long id) {
    33	        requireVehicle(vehicleId);
    34	        return VehicleDocumentMapper.toResponse(getDocument(vehicleId, id));
    35	    }
    36	
    37	    @Transactional
    38	    public VehicleDocumentResponse create(Long vehicleId, VehicleDocumentRequest request) {
    39	        requireVehicle(vehicleId);
    40	        // Checked only here, in the transaction (INTENT.md Z8): H2 has no partial unique index.
    41	        if (documentRepository.existsByVehicleIdAndTypeAndStatusNot(vehicleId, request.type(),
    42	                VehicleDocumentStatus.REJECTED)) {
    43	            throw new ConflictException("Vehicle with id " + vehicleId + " already has an active document of type "
    44	                    + request.type());
    45	        }
    46	        VehicleDocument document = documentRepository.save(VehicleDocumentMapper.toEntity(vehicleId, request));
    47	        return VehicleDocumentMapper.toResponse(document);
    48	    }
    49	
    50	    @Transactional
    51	    public VehicleDocumentResponse changeStatus(Long vehicleId, Long id, VehicleDocumentStatusRequest request) {
    52	        requireVehicle(vehicleId);
    53	        VehicleDocument document = getDocument(vehicleId, id);
    54	        if (!VehicleDocumentStatusTransitions.isAllowed(document.getStatus(), request.status())) {
    55	            throw new ConflictException("Document with id " + id + " cannot change status from "
    56	                    + document.getStatus() + " to " + request.status());
    57	        }
    58	        document.changeStatus(request.status());
    59	        return VehicleDocumentMapper.toResponse(documentRepository.save(document));
    60	    }
